<script setup lang="ts">
import { ArrowDownRight, ArrowUpRight, CheckCircle2, Download, Plus, RefreshCcw, Search, ShieldCheck, WalletCards } from 'lucide-vue-next';
import { computed, reactive, ref } from 'vue';
import StatePanel from '../../components/StatePanel.vue';
import StatusBadge from '../../components/StatusBadge.vue';
import { useResource } from '../../composables/useResource';
import { api } from '../../lib/api';
import { formatDate, formatDateTime, formatRupiah } from '../../lib/format';
import { adaptBills, adaptFinanceTransactions, adaptHouseholds, adaptPayments, type FinanceTransactionView, type PaymentView } from '../../lib/view-models';

type Section='bills'|'payments'|'ledger';
const props=withDefaults(defineProps<{section?:Section}>(),{section:'ledger'});
const bills=useResource(async()=>adaptBills(await api.get<unknown>('/bills')));
const payments=useResource(async()=>adaptPayments(await api.get<unknown>('/payments')));
const transactions=useResource(async()=>adaptFinanceTransactions(await api.get<unknown>('/finance/transactions')));
const households=useResource(async()=>adaptHouseholds(await api.get<unknown>('/households')));
const search=ref('');const panelOpen=ref(false);const message=ref('');const busy=ref('');
const billForm=reactive({householdId:'',title:'Iuran lingkungan',description:'Keamanan, kebersihan, dan kas sosial.',period:'Agustus 2026',dueAt:'2026-08-31',amount:150000,kind:'MANDATORY',recurrence:'MONTHLY'});
const transactionForm=reactive({kind:'EXPENSE',category:'Pemeliharaan',description:'',amount:0,occurredAt:'2026-07-27'});
const title=computed(()=>({bills:'Tagihan warga',payments:'Verifikasi pembayaran',ledger:'Kas & laporan keuangan'}[props.section]));
const pending=computed(()=>payments.data.value?.filter(item=>item.status==='PENDING_VERIFICATION')??[]);
const income=computed(()=>transactions.data.value?.filter(item=>item.kind==='INCOME').reduce((sum,item)=>sum+item.amount,0)??0);
const expense=computed(()=>transactions.data.value?.filter(item=>item.kind==='EXPENSE').reduce((sum,item)=>sum+item.amount,0)??0);
async function verify(item:PaymentView){busy.value=item.id;try{await api.post(`/payments/${item.id}/verify`);item.status='PAID';message.value=`Pembayaran ${item.submitterLabel} telah diverifikasi dan dicatat ke kas.`}finally{busy.value=''}}
async function createBill(){await api.post('/bills',{...billForm,dueAt:new Date(`${billForm.dueAt}T23:59:59+07:00`).toISOString()});message.value='Tagihan dibuat untuk rumah terpilih.';panelOpen.value=false;await bills.reload()}
async function createTransaction(){await api.post('/finance/transactions',{...transactionForm,occurredAt:new Date(`${transactionForm.occurredAt}T12:00:00+07:00`).toISOString()});message.value='Transaksi disimpan sebagai draf.';panelOpen.value=false}
async function reverse(item:FinanceTransactionView){const reason=window.prompt('Tuliskan alasan koreksi (wajib):');if(!reason?.trim())return;await api.post(`/finance/transactions/${item.id}/reverse`,{reason});message.value='Reversal tercatat. Transaksi sumber tidak dihapus.'}
</script>

<template><div class="admin-page"><header class="admin-heading"><div><span class="eyebrow">Keuangan yang dapat diaudit</span><h1>{{ title }}</h1><p v-if="section==='payments'">Verifikasi bukti satu kali. Tindakan ini membuat pemasukan dan jejak audit secara atomik.</p><p v-else-if="section==='bills'">Buat tagihan per rumah tanpa memperlihatkan tunggakan kepada warga lain.</p><p v-else>Transaksi posted tidak dapat dihapus; koreksi selalu dibuat sebagai reversal.</p></div><div class="heading-actions"><a v-if="section==='ledger'" class="button button-secondary" href="/api/v1/finance/export.csv"><Download :size="16"/> Ekspor CSV</a><button v-if="section!=='payments'" class="button" type="button" @click="panelOpen=true"><Plus :size="16"/> {{ section==='bills'?'Buat tagihan':'Catat transaksi' }}</button></div></header><div v-if="message" class="notice" role="status"><CheckCircle2 :size="18"/>{{ message }}</div>

<template v-if="section==='bills'"><div class="finance-metrics"><article><span>Total diterbitkan</span><strong>{{ formatRupiah(bills.data.value?.reduce((sum,item)=>sum+item.amount,0)??0) }}</strong></article><article><span>Tagihan terbuka</span><strong>{{ bills.data.value?.filter(item=>item.status==='OPEN').length??0 }}</strong></article><article><span>Tagihan lunas</span><strong>{{ bills.data.value?.filter(item=>item.status==='PAID').length??0 }}</strong></article></div><StatePanel v-if="bills.loading.value" state="loading"/><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>Tagihan</th><th>Periode</th><th>Jatuh tempo</th><th>Nominal</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in bills.data.value" :key="item.id"><td><strong>{{ item.title }}</strong><small>{{ item.description }}</small></td><td>{{ item.period }}</td><td>{{ formatDate(item.dueAt) }}</td><td>{{ formatRupiah(item.amount) }}</td><td><StatusBadge :status="item.status"/></td><td><button class="row-action" type="button">Detail</button></td></tr></tbody></table></div></template>

<template v-else-if="section==='payments'"><div class="notice notice-warning"><ShieldCheck :size="18"/><span>Bukti transfer bersifat privat. Jangan mengunduh atau menyebarkan bukti di luar kebutuhan rekonsiliasi.</span></div><div class="toolbar"><label><Search :size="16"/><span class="sr-only">Cari pembayaran</span><input v-model="search" type="search" placeholder="Cari warga atau tagihan"/></label><span>{{ pending.length }} menunggu pemeriksaan</span></div><StatePanel v-if="payments.loading.value" state="loading"/><div v-else class="payment-list"><article v-for="item in payments.data.value?.filter(payment=>`${payment.resident} ${payment.bill}`.toLowerCase().includes(search.toLowerCase()))" :key="item.id" class="card card-body"><span class="payment-icon"><WalletCards :size="20"/></span><div><h2>{{ item.resident }}</h2><p>{{ item.bill }} · Dikirim {{ formatDateTime(item.submittedAt) }}</p><strong>{{ formatRupiah(item.amount) }}</strong></div><StatusBadge :status="item.status"/><div class="payment-actions"><a v-if="item.proofUrl" class="button button-secondary button-sm" :href="item.proofUrl" target="_blank" rel="noopener" :aria-label="`Lihat bukti pembayaran ${item.submitterLabel}`">Lihat bukti</a><span v-else class="muted small">Tanpa bukti file</span><button v-if="item.status==='PENDING_VERIFICATION'" class="button button-sm" type="button" :disabled="busy===item.id" @click="verify(item)">{{ busy===item.id?'Memproses…':'Verifikasi pembayaran' }}</button><span v-else class="verified"><CheckCircle2 :size="16"/> Selesai</span></div></article></div></template>

<template v-else><dl class="ledger-summary"><div><dt><ArrowUpRight :size="16"/>Pemasukan</dt><dd>{{ formatRupiah(income) }}</dd></div><div><dt><ArrowDownRight :size="16"/>Pengeluaran</dt><dd>{{ formatRupiah(expense) }}</dd></div><div><dt>Saldo berdasarkan entri</dt><dd>{{ formatRupiah(income-expense) }}</dd></div></dl><div class="toolbar"><label><Search :size="16"/><span class="sr-only">Cari transaksi</span><input v-model="search" type="search" placeholder="Cari deskripsi atau kategori"/></label><button class="button button-secondary button-sm" type="button">Semua kategori</button></div><StatePanel v-if="transactions.loading.value" state="loading"/><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Deskripsi</th><th>Kategori</th><th>Jenis</th><th>Nominal</th><th>Tindakan</th></tr></thead><tbody><tr v-for="item in transactions.data.value?.filter(transaction=>`${transaction.description} ${transaction.category}`.toLowerCase().includes(search.toLowerCase()))" :key="item.id"><td>{{ item.date }}</td><td><strong>{{ item.description }}</strong></td><td>{{ item.category }}</td><td><span :class="['kind',item.kind.toLowerCase()]">{{ item.kind==='INCOME'?'Pemasukan':'Pengeluaran' }}</span></td><td :class="item.kind.toLowerCase()">{{ item.kind==='EXPENSE'?'-':'+' }}{{ formatRupiah(item.amount) }}</td><td><button class="row-action" type="button" @click="reverse(item)"><RefreshCcw :size="14"/> Koreksi</button></td></tr></tbody></table></div></template>

<aside v-if="panelOpen" class="side-panel"><div class="panel-heading"><div><span class="eyebrow">Pencatatan terkontrol</span><h2>{{ section==='bills'?'Buat tagihan':'Catat transaksi kas' }}</h2></div><button type="button" aria-label="Tutup panel" @click="panelOpen=false">×</button></div><form v-if="section==='bills'" class="form-grid" @submit.prevent="createBill"><div class="field"><label for="bill-household">Rumah penerima tagihan</label><select id="bill-household" v-model="billForm.householdId" required><option value="" disabled>Pilih rumah</option><option v-for="household in households.data.value" :key="household.id" :value="household.id">{{ household.code }} · {{ household.address }}</option></select><small>Tagihan hanya terlihat oleh anggota rumah yang dipilih.</small></div><div class="field"><label for="bill-title">Nama tagihan</label><input id="bill-title" v-model="billForm.title" minlength="4" required/></div><div class="two-fields"><div class="field"><label for="bill-period">Periode</label><input id="bill-period" v-model="billForm.period" required/></div><div class="field"><label for="bill-due">Jatuh tempo</label><input id="bill-due" v-model="billForm.dueAt" type="date" required/></div></div><div class="field"><label for="bill-amount">Nominal rumah</label><input id="bill-amount" v-model.number="billForm.amount" type="number" min="1" required/></div><div class="field"><label for="bill-description">Penggunaan dana</label><textarea id="bill-description" v-model="billForm.description" minlength="10" required/></div><div class="notice notice-warning">Periksa rumah, periode, dan nominal sebelum membuat tagihan.</div><button class="button" type="submit">Buat tagihan</button></form><form v-else class="form-grid" @submit.prevent="createTransaction"><div class="two-fields"><div class="field"><label for="transaction-kind">Jenis</label><select id="transaction-kind" v-model="transactionForm.kind"><option value="INCOME">Pemasukan</option><option value="EXPENSE">Pengeluaran</option></select></div><div class="field"><label for="transaction-date">Tanggal</label><input id="transaction-date" v-model="transactionForm.occurredAt" type="date" required/></div></div><div class="field"><label for="transaction-description">Deskripsi</label><input id="transaction-description" v-model="transactionForm.description" minlength="5" required/></div><div class="field"><label for="transaction-category">Kategori</label><input id="transaction-category" v-model="transactionForm.category" required/></div><div class="field"><label for="transaction-amount">Nominal</label><input id="transaction-amount" v-model.number="transactionForm.amount" type="number" min="1" required/></div><button class="button" type="submit">Simpan sebagai draf</button></form></aside></div></template>

<style scoped>.admin-page{display:grid;max-width:88rem;gap:1.2rem;margin-inline:auto}.admin-heading{display:flex;align-items:end;justify-content:space-between;gap:1rem}.admin-heading h1{margin-bottom:.4rem;font-size:clamp(2rem,4vw,3rem)}.admin-heading p{max-width:52rem;margin:0;color:var(--ink-650)}.heading-actions{display:flex;gap:.6rem}.finance-metrics,.ledger-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:.7rem;margin:0}.finance-metrics article,.ledger-summary div{display:grid;padding:1rem;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--paper)}.finance-metrics span,.ledger-summary dt{display:flex;align-items:center;gap:.3rem;color:var(--ink-650);font-size:.75rem}.finance-metrics strong,.ledger-summary dd{margin:.35rem 0 0;font-size:1.3rem;font-weight:850}.ledger-summary div:last-child{border-color:var(--teal-700);background:var(--ink-950);color:white}.ledger-summary div:last-child dt{color:rgb(255 255 255/.6)}.toolbar{display:flex;align-items:center;gap:.6rem;padding:.7rem;border:1px solid var(--line);border-radius:var(--radius-md);background:var(--paper)}.toolbar label{display:flex;max-width:30rem;flex:1;align-items:center;gap:.4rem;padding-inline:.65rem;border:1px solid var(--line-strong);border-radius:.65rem;color:var(--ink-500)}.toolbar input{width:100%;min-height:2.5rem;border:0;outline:0}.toolbar>span{margin-left:auto;color:var(--ink-650);font-size:.78rem}.data-table td:first-child small{display:block;color:var(--ink-650)}.row-action{display:inline-flex;min-height:2.5rem;align-items:center;gap:.3rem;padding:.45rem .6rem;border:1px solid var(--line);border-radius:.6rem;background:white;color:var(--teal-700);font-size:.76rem;font-weight:750;cursor:pointer}.payment-list{display:grid;gap:.65rem}.payment-list article{display:grid;grid-template-columns:auto minmax(0,1fr) auto auto;align-items:center;gap:.8rem}.payment-icon{display:grid;width:2.7rem;height:2.7rem;place-items:center;border-radius:.75rem;background:var(--amber-100);color:var(--amber-700)}.payment-list h2{margin:0;font-size:1rem}.payment-list p{margin:.1rem 0;color:var(--ink-650);font-size:.75rem}.payment-list strong{font-size:.92rem}.payment-actions{display:flex;gap:.45rem}.verified{display:inline-flex;align-items:center;gap:.3rem;color:var(--success-700);font-size:.78rem;font-weight:750}.kind{padding:.25rem .45rem;border-radius:999px;font-size:.7rem;font-weight:800}.kind.income{background:var(--success-100);color:var(--success-700)}.kind.expense{background:var(--coral-100);color:var(--coral-700)}td.income{color:var(--success-700);font-weight:750}td.expense{color:var(--coral-700);font-weight:750}.side-panel{position:fixed;z-index:50;top:0;right:0;width:min(100%,35rem);height:100vh;padding:1.5rem;overflow-y:auto;border-left:1px solid var(--line);background:var(--paper);box-shadow:var(--shadow-lg)}.panel-heading{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:1.3rem}.panel-heading button{width:2.75rem;height:2.75rem;border:1px solid var(--line);border-radius:.7rem;background:white;font-size:1.5rem}.two-fields{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}@media(max-width:850px){.admin-heading{align-items:flex-start;flex-direction:column}.payment-list article{grid-template-columns:auto 1fr}.payment-list article>.status-badge{grid-column:2}.payment-actions{grid-column:1/-1}.finance-metrics,.ledger-summary{grid-template-columns:1fr}}@media(max-width:520px){.heading-actions,.heading-actions .button{width:100%}.two-fields{grid-template-columns:1fr}}</style>
